// Entradas: 'tick' · respuestas mysql · db_error · cx_snapshot_req
// Salida 1 → mysql · Salida 2 → navegador
//
// Motor 100% GMX→GMX. Reloj = md_gmx.last[symbol].source_ts.
// Serie de 1 s as-of backward: para el boundary T se usa la última
// cotización con source_ts <= T, con carry-forward hasta 10 s.
//
// CONCEPTITO_MOVEMENT_V1
// Habilitación MOVIMIENTO ZEC ON/OFF: rango causal de los últimos 30 min
// sobre el GMX MID de 1 s. range30_bps = (max30 - min30) / precio * 10000.
// MOVIMIENTO_ON = range30_bps >= 66.04. Con OFF (o WARMUP) los cruces se
// siguen calculando pero no abren posición; una posición abierta se
// administra normalmente hasta TP / SL / ESCAPE_DIR / TIMEOUT.
//
// CONCEPTITO_X10_V2_ESCAPE
// Base idéntica a CONCEPTITO_X10_V1. Dos diferencias experimentales:
// 1) ESCAPE_DIR (abajo) y 2) ENTRY_SPACING (ver más abajo).
// ESCAPE_DIR: salida anticipada. Una posición se ARMA (y no se desarma) cuando
// su MFE >= escapeArmMfeUsd. Armada, se considera direccionalidad adversa
// cuando, en el mismo segundo procesado t (todo causal, datos <= t):
//   LONG : slope35 < 0, slope70 < 0, spread < spreadLag
//   SHORT: slope35 > 0, slope70 > 0, spread > spreadLag
//   y además giveback = MFE - PnL >= escapeGivebackUsd
//   y PnL bruto actual > 0 (si escapeOnlyIfPositive).
//   slopeXBps = (SMA_X(t) / SMA_X(t - 5 s) - 1) * 10000
//   spreadBps = (SMA35(t) / SMA70(t) - 1) * 10000 · spreadLag = spread(t - 5 s)
// Si se cumple escapeConfirmSec segundos procesados consecutivos → cierre
// ESCAPE_DIR al GMX ejecutable de ese segundo (misma gmxPx de V1), bruto
// REAL a ese precio y fee de salida igual a V1.
// Prioridad en el mismo segundo: TP > SL > ESCAPE_DIR > TIMEOUT.
//
// V2 · ENTRY_SPACING (segunda diferencia experimental respecto de V1)
// Separación GLOBAL mínima de C.entrySpacingMin minutos entre APERTURAS
// EFECTIVAS, sin importar LONG/SHORT. Se evalúa al aparecer un cruce
// válido (después de cooldown 32 s, MOVEMENT y capacidad), antes de crear
// E.pend, con candidateEntryT = b.t + 1000 (entrada N+1). Si no pasó el
// spacing: no hay pend, rejectEntrySpacing++, lastEntryT NO cambia.
// lastEntryT sólo se actualiza dentro de open() tras una apertura exitosa.
// El cooldown cross-to-cross de 32 s mantiene exactamente su comportamiento.

const ENGINE = 'CONCEPTITO_X10_V2_ESCAPE';

const E = context.get('E', 'memory');

if (!E || !E.cfg) {
    node.warn(ENGINE + ': estado E / E.cfg no inicializado (revisar On Start)');
    return null;
}

const C = E.cfg;
const now = Date.now();

const out = [null, null];

const CROSS_COOLDOWN_MS = 32000;
const GMX_MAX_AGE_MS = 10000;
// Identificador de la simulación en MariaDB. Al cambiarlo, el restore
// arranca limpio (OPS/TP/SL/TO/PnL/fees = 0, sin trades ni posición).
// Source propio de V2: jamás mezcla filas con 'GMX_MOV_X10_V1'.
const SRC = 'GMX_MOV_X10_V2_ESCAPE';

const MOVE_WINDOW_MS = 30 * 60000;
const MOVE_THRESHOLD_BPS = 66.04;

// ============================================================
// PARÁMETROS ESCAPE_DIR (V2) — cambiar sólo aquí
// ============================================================

const ESC = {
    escapeArmMfeUsd: 15.00,       // arma la protección cuando MFE >= 15 USD (no se desarma)
    escapeGivebackUsd: 5.00,      // MFE - PnL bruto actual >= 5 USD
    escapeSlopeWindowSec: 5,      // SMA(t) vs SMA(t - 5 s) y spread(t) vs spread(t - 5 s)
    escapeConfirmSec: 3,          // segundos procesados consecutivos con condición adversa
    escapeOnlyIfPositive: true,   // exige PnL bruto actual > 0
    mfeCheckpointStepUsd: 2.50    // persiste mfe/mae en la fila OPEN al armar y cada +2.50 de MFE
};

// Buffer de SMA35/SMA70 por segundo (suficiente para t - escapeSlopeWindowSec).
const SMA_BUF_LEN = ESC.escapeSlopeWindowSec + 5;


// ============================================================
// INICIALIZACIÓN DEFENSIVA
// ============================================================

function def(k, v) {
    if (E[k] === undefined) {
        E[k] = v;
    }
}

def('phase', 'RESTAURANDO');

if (!Array.isArray(E.q)) E.q = [];
def('inflight', null);
def('seq', 0);
def('backoff', 0);
def('nextTry', 0);
def('dbOk', false);
def('dbErr', '');
def('dbErrors', 0);
def('saved', 0);
def('lastLogAt', 0);
def('lastItem', null);

if (!Array.isArray(E.positions)) E.positions = [];
def('pend', null);
def('rejectMaxPositions', 0);

// ENTRY_SPACING (V2)
def('lastEntryT', 0);
def('rejectEntrySpacing', 0);
if (!(Number(C.entrySpacingMin) >= 0)) C.entrySpacingMin = 5;
const ENTRY_SPACING_MS = Number(C.entrySpacingMin) * 60000;
def('signalsAccepted', 0);
def('lastRejected', null);

if (!Array.isArray(E.closes)) E.closes = [];
def('sF', null);
def('sS', null);
def('lastSign', 0);
def('lastCrossT', 0);
def('last', null);
def('lastClosed', null);

if (!E.totals) {
    E.totals = { ops: 0, tp: 0, sl: 0, escape: 0, to: 0, gross: 0, net: 0, fees: 0 };
}

if (E.totals.gross === undefined) E.totals.gross = 0;
if (E.totals.escape === undefined) E.totals.escape = 0;

// ESCAPE_DIR (V2)
if (!Array.isArray(E.smaBuf)) E.smaBuf = [];
if (!E.esc) {
    E.esc = { t: 0, slopeFastBps: null, slopeSlowBps: null, spreadBps: null, spreadBpsLag: null };
}
def('escapeEnabled', true);
def('schemaInfo', 'sin verificar');
def('escapeArms', 0);
def('escapeConfirmResets', 0);

if (!Array.isArray(E.trades)) E.trades = [];
def('tradesRev', 0);
def('sentRev', -1);

if (!Array.isArray(E.newPts)) E.newPts = [];
def('dirty', false);
def('lastEmit', 0);

def('gaps', 0);
def('ignored', 0);
def('openRows', 0);
def('replayUntil', 0);

def('lastBucketT', 0);
def('lastGmxSourceTs', 0);
def('lastGmxQuote', null);
def('nextGmxBoundary', 0);

// MOVIMIENTO ZEC 30 min
if (!Array.isArray(E.r30)) E.r30 = [];
def('r30Since', 0);
def('r30High', null);
def('r30Low', null);
def('r30Bps', null);
def('moveState', 'WARMUP');
def('crossesBlockedMovement', 0);
def('crossesBlockedWarmup', 0);

if (!E.hist || !E.hist.cap || !E.hist.idx || !E.hist.a || !E.hist.b) {
    const cap = Math.max(60, Math.floor(Number(C.histSec) || 3600));

    E.hist = {
        cap: cap,
        idx: new Float64Array(cap),
        a: new Float64Array(cap),
        b: new Float64Array(cap)
    };
}


// ============================================================
// HELPERS
// ============================================================

function pad(n, w) {
    return String(n).padStart(w || 2, '0');
}

function dt(t) {
    const d = new Date(t);

    return (
        d.getUTCFullYear() + '-' +
        pad(d.getUTCMonth() + 1) + '-' +
        pad(d.getUTCDate()) + ' ' +
        pad(d.getUTCHours()) + ':' +
        pad(d.getUTCMinutes()) + ':' +
        pad(d.getUTCSeconds()) + '.' +
        pad(d.getUTCMilliseconds(), 3)
    );
}

function r(v, d) {
    return v == null ? null : Number(v.toFixed(d));
}

function num(v) {
    return v == null ? null : Number(v);
}

function enqueue(item) {
    E.q.push(item);

    if (E.q.length > 1000) {
        E.q.shift();
        E.dbErrors++;
        E.dbErr = 'cola DB llena: se descartó la escritura más vieja';
    }
}

function fail(reason) {
    const m = String(reason).slice(0, 200);

    if (m !== E.dbErr || now - E.lastLogAt > 60000) {
        node.warn(ENGINE + ' DB: ' + m);
        E.lastLogAt = now;
    }

    E.dbErrors++;
    E.dbErr = m;
    E.dbOk = false;

    if (E.inflight && E.inflight.item) {
        E.q.unshift(E.inflight.item);
    }

    E.inflight = null;

    E.backoff = Math.min(
        60000,
        Math.max(3000, E.backoff * 2)
    );

    E.nextTry = now + E.backoff;
}

function resetSignal() {
    E.closes = [];

    E.sF = null;
    E.sS = null;

    E.lastSign = 0;

    // V2: el buffer de slopes también pierde continuidad (no afecta entradas).
    resetEscapeMetrics();
}

function resetEscapeMetrics() {
    E.smaBuf = [];
    E.esc = {
        t: 0,
        slopeFastBps: null,
        slopeSlowBps: null,
        spreadBps: null,
        spreadBpsLag: null
    };
}


// ============================================================
// MOVIMIENTO ZEC ON/OFF (rango causal 30 min)
// ============================================================

function resetMovement() {
    E.r30 = [];
    E.r30Since = 0;

    E.r30High = null;
    E.r30Low = null;
    E.r30Bps = null;

    E.moveState = 'WARMUP';
}

// t = boundary del segundo, px = GMX MID de ese segundo.
// Sólo usa precios con t' <= t (sin look-ahead).
function movePut(t, px) {
    const R = E.r30;

    // Ventana (t - 30 min, t]
    while (R.length && R[0].t <= t - MOVE_WINDOW_MS) {
        R.shift();
    }

    if (!R.length) {
        E.r30Since = t;
    }

    R.push({ t: t, px: px });

    let hi = -Infinity;
    let lo = Infinity;

    for (let i = 0; i < R.length; i++) {
        if (R[i].px > hi) hi = R[i].px;
        if (R[i].px < lo) lo = R[i].px;
    }

    E.r30High = hi;
    E.r30Low = lo;
    E.r30Bps = (hi - lo) / px * 10000;

    // Warm-up: 30 min de historia (1800 segundos) desde que arrancó el buffer.
    const warm = t - E.r30Since >= MOVE_WINDOW_MS - 1000;

    const st = !warm
        ? 'WARMUP'
        : (E.r30Bps >= MOVE_THRESHOLD_BPS ? 'ON' : 'OFF');

    if (st !== E.moveState) {
        node.log(
            ENGINE + ': MOVEMENT ' + E.moveState + ' → ' + st +
            ' (range30 ' + E.r30Bps.toFixed(2) + ' bps · umbral ' +
            MOVE_THRESHOLD_BPS + ' · ' +
            new Date(t).toISOString().slice(11, 19) + ')'
        );

        E.moveState = st;
        E.dirty = true;
    }
}

function moveWarmSec() {
    if (!E.r30.length || !E.last) return 0;

    return Math.min(
        MOVE_WINDOW_MS / 1000,
        Math.round((E.last.t - E.r30Since) / 1000) + 1
    );
}


// ============================================================
// PERSISTENCIA
// ============================================================

const COLS = [
    'symbol',
    'source',
    'status',
    'signal_ts',
    'entry_ts',
    'exit_ts',
    'side',
    'entry_price',
    'exit_price',
    'exit_trigger_price',
    'qty',
    'margin_usd',
    'leverage',
    'exposure_usd',
    'sma_fast',
    'sma_slow',
    'sma_fast_entry',
    'sma_slow_entry',
    'tp_usd',
    'sl_usd',
    'timeout_min',
    'fee_rate',
    'gross_pnl',
    'fee_entry',
    'fee_exit',
    'fees',
    'net_pnl',
    'exit_reason',
    'duration_seconds',
    'mfe_usd',
    'mae_usd'
];

const UPD = [
    'status',
    'exit_ts',
    'exit_price',
    'exit_trigger_price',
    'gross_pnl',
    'fee_exit',
    'fees',
    'net_pnl',
    'exit_reason',
    'duration_seconds',
    'mfe_usd',
    'mae_usd'
];

function saveRow(p, x) {

    const row = [
        C.symbol,
        SRC,
        x ? 'CLOSED' : 'OPEN',

        dt(p.signalT),
        dt(p.entryT),
        x ? dt(x.t) : null,

        p.side,
        p.entryPx,
        x ? r(x.px, 8) : null,
        x ? x.trigger : null,

        r(p.qty, 10),

        p.margin,
        p.lev,
        p.exposure,

        p.fast,
        p.slow,

        r(p.sFast, 8),
        r(p.sSlow, 8),

        p.tp,
        p.sl,
        p.toMin,
        p.feeRate,

        x ? r(x.gross, 4) : null,
        r(p.feeEntry, 4),
        x ? r(x.feeExit, 4) : null,
        x ? r(x.fees, 4) : null,
        x ? r(x.net, 4) : null,

        x ? x.reason : null,
        x ? x.dur : null,

        x ? r(p.mfe, 4) : null,
        x ? r(p.mae, 4) : null
    ];

    const upsert = {
        kind: 'save',
        row: row,

        sql:
            'INSERT INTO ' + C.table +
            ' (' + COLS.join(', ') + ') VALUES ? ' +
            'ON DUPLICATE KEY UPDATE ' +
            UPD.map(function (c) {
                return c + ' = VALUES(' + c + ')';
            }).join(', '),

        params: [[row]]
    };

    if (!x) {
        enqueue(upsert);
        return;
    }

    const vals = UPD.map(function (c) {
        return row[COLS.indexOf(c)];
    });

    enqueue({
        kind: 'close',
        row: row,
        fallback: upsert,

        sql:
            'UPDATE ' + C.table +
            ' SET ' +
            UPD.map(function (c) {
                return c + ' = ?';
            }).join(', ') +
            ' WHERE symbol = ? AND source = ? AND entry_ts = ?',

        params: vals.concat([
            C.symbol,
            SRC,
            dt(p.entryT)
        ])
    });
}

// V2: checkpoint de MFE/MAE sobre la fila OPEN (columnas ya existentes
// mfe_usd / mae_usd; sin cambio de schema). Permite que el restore
// recupere MFE y el estado ARMED. El contador de confirmación no se
// persiste: tras restart/deploy arranca en 0.
function saveMfeCheckpoint(p) {
    p.mfeSaved = p.mfe;

    enqueue({
        kind: 'mfe',
        row: null,

        sql:
            'UPDATE ' + C.table +
            ' SET mfe_usd = ?, mae_usd = ?' +
            ' WHERE symbol = ? AND source = ? AND entry_ts = ? AND status = \'OPEN\'',

        params: [
            r(p.mfe, 4),
            r(p.mae, 4),
            C.symbol,
            SRC,
            dt(p.entryT)
        ]
    });
}


// ============================================================
// SMA / HISTORIAL
// ============================================================

function avgLast(n) {
    const a = E.closes;

    if (a.length < n) return null;

    let s = 0;

    for (let i = a.length - n; i < a.length; i++) {
        s += a[i];
    }

    return s / n;
}

function histPut(t, a, b) {
    const H = E.hist;
    const sec = Math.floor(t / 1000);
    const k = sec % H.cap;

    H.idx[k] = sec;
    H.a[k] = a == null ? NaN : a;
    H.b[k] = b == null ? NaN : b;
}

// V2: guarda SMA35/SMA70 del segundo t y calcula métricas causales de
// direccionalidad contra el segundo t - escapeSlopeWindowSec (lookup por
// timestamp exacto: si falta ese segundo, las métricas quedan null).
function escapeMetrics(t, sF, sS) {
    const lagMs = ESC.escapeSlopeWindowSec * 1000;

    const m = {
        t: t,
        slopeFastBps: null,
        slopeSlowBps: null,
        spreadBps: null,
        spreadBpsLag: null
    };

    if (sF == null || sS == null || !(sF > 0) || !(sS > 0)) {
        E.esc = m;
        return m;
    }

    const spread = (sF / sS - 1) * 10000;

    const B = E.smaBuf;
    B.push({ t: t, sF: sF, sS: sS, spread: spread });
    while (B.length > SMA_BUF_LEN) B.shift();

    m.spreadBps = spread;

    let lag = null;
    for (let i = B.length - 1; i >= 0; i--) {
        if (B[i].t === t - lagMs) { lag = B[i]; break; }
        if (B[i].t < t - lagMs) break;
    }

    if (lag) {
        m.slopeFastBps = (sF / lag.sF - 1) * 10000;
        m.slopeSlowBps = (sS / lag.sS - 1) * 10000;
        m.spreadBpsLag = lag.spread;
    }

    E.esc = m;
    return m;
}

function escapeAdverse(p, gross, giveback, m) {
    if (!E.escapeEnabled) return false;
    if (!p.escapeArmed) return false;

    if (
        !m ||
        m.slopeFastBps == null ||
        m.slopeSlowBps == null ||
        m.spreadBps == null ||
        m.spreadBpsLag == null
    ) {
        return false;
    }

    if (giveback < ESC.escapeGivebackUsd) return false;
    if (ESC.escapeOnlyIfPositive && !(gross > 0)) return false;

    if (p.side === 'LONG') {
        return (
            m.slopeFastBps < 0 &&
            m.slopeSlowBps < 0 &&
            m.spreadBps < m.spreadBpsLag
        );
    }

    return (
        m.slopeFastBps > 0 &&
        m.slopeSlowBps > 0 &&
        m.spreadBps > m.spreadBpsLag
    );
}

function escapeLabel(p) {
    if (!p.escapeArmed) return 'OFF';
    if (p.escapeConfirm > 0) return p.escapeConfirm + '/' + ESC.escapeConfirmSec;
    return 'ARMED';
}

// V2 ENTRY_SPACING: segundos que faltan para que una entrada N+1 sea válida.
// Reloj = último segundo GMX procesado (sin datos aún: Date.now()).
function spacingRemainingSec() {
    if (!E.lastEntryT || !(ENTRY_SPACING_MS > 0)) return 0;
    const candidate = (E.last && E.last.t ? E.last.t : now) + 1000;
    return Math.max(0, Math.ceil((E.lastEntryT + ENTRY_SPACING_MS - candidate) / 1000));
}

function levels(p) {
    const k = p.side === 'LONG' ? 1 : -1;

    return {
        tpPx:
            p.entryPx *
            (1 + k * p.tp / p.exposure),

        slPx:
            p.entryPx *
            (1 + k * p.sl / p.exposure)
    };
}


// ============================================================
// GMX
// ============================================================

// q = cotización asociada al segundo procesado:
// { t, source_ts, min, max, mid }
function gmxPx(q, side, action) {

    if (
        !q ||
        !isFinite(q.min) ||
        !isFinite(q.max) ||
        !isFinite(q.t) ||
        !isFinite(q.source_ts) ||
        q.source_ts > q.t ||
        q.t - q.source_ts > GMX_MAX_AGE_MS
    ) {
        return null;
    }

    // LONG:
    // entrada max / salida min
    //
    // SHORT:
    // entrada min / salida max

    return action === 'ENTRY'
        ? (
            side === 'LONG'
                ? q.max
                : q.min
        )
        : (
            side === 'LONG'
                ? q.min
                : q.max
        );
}


// ============================================================
// ABRIR POSICIÓN X10
// ============================================================

function usedSlots() {
    const used = new Set();
    for (let i = 0; i < E.positions.length; i++) {
        const s = Number(E.positions[i].slot);
        if (s >= 1 && s <= C.maxPos) used.add(s);
    }
    return used;
}

function nextFreeSlot() {
    const used = usedSlots();
    for (let s = 1; s <= C.maxPos; s++) {
        if (!used.has(s)) return s;
    }
    return null;
}

function open(sig, b) {
    if (E.positions.length >= C.maxPos) {
        E.rejectMaxPositions++;
        E.lastRejected = { reason: 'REJECT_MAX_POSITIONS', t: sig.t, side: sig.side };
        E.dirty = true;
        return false;
    }

    const exposure = C.margin * C.lev;
    const px = gmxPx(b, sig.side, 'ENTRY');

    if (px == null) {
        node.warn(ENGINE + ': entrada omitida; GMX sin cotización válida en N+1');
        return false;
    }

    const slot = nextFreeSlot();
    if (slot == null) {
        E.rejectMaxPositions++;
        E.lastRejected = { reason: 'REJECT_MAX_POSITIONS', t: sig.t, side: sig.side };
        E.dirty = true;
        return false;
    }

    const p = {
        slot: slot,
        signalId: sig.signalId || (String(sig.t) + ':' + sig.side),
        side: sig.side,
        signalT: sig.t,
        entryT: b.t,
        entryPx: px,
        qty: exposure / px,
        margin: C.margin,
        lev: C.lev,
        exposure: exposure,
        fast: C.fast,
        slow: C.slow,
        sFast: sig.sF,
        sSlow: sig.sS,
        tp: C.tp,
        sl: C.sl,
        toMin: C.timeoutMin,
        feeRate: C.feeRate,
        feeBase: C.feeBase,
        feeEntry: exposure * C.feeRate,
        pnl: 0,
        mfe: 0,
        mae: 0,
        lastPx: px,
        lastT: b.t,

        // ESCAPE_DIR (V2)
        giveback: 0,
        escapeArmed: false,
        escapeConfirm: 0,
        escapeLastT: 0,
        mfeSaved: 0,
        restored: false
    };

    E.positions.push(p);
    saveRow(p, null);

    // V2 ENTRY_SPACING: sólo una apertura EFECTIVA mueve el reloj.
    E.lastEntryT = b.t;

    E.trades.push({
        slot: slot,
        signalId: p.signalId,
        entryT: b.t,
        entryPx: px,
        side: sig.side
    });

    E.tradesRev++;

    node.log(
        ENGINE + ': abre slot ' + slot + ' ' + sig.side + ' GMX @ ' + px +
        ' (señal GMX MID; cruce en ' + new Date(sig.t).toISOString().slice(11, 19) + ')' +
        ' · abiertas ' + E.positions.length + '/' + C.maxPos
    );

    return true;
}


// ============================================================
// GESTIÓN DE POSICIONES X10
// ============================================================

function managePosition(p, b, m) {
    const k = p.side === 'LONG' ? 1 : -1;
    const px = gmxPx(b, p.side, 'EXIT');

    if (px == null) return false;

    const gross = k * p.qty * (px - p.entryPx);

    // Continuidad de segundos procesados para la confirmación ESCAPE_DIR.
    const contiguous = p.escapeLastT > 0 && b.t - p.escapeLastT === 1000;

    p.pnl = gross;
    p.lastPx = px;
    p.lastT = b.t;
    p.escapeLastT = b.t;

    if (gross > p.mfe) p.mfe = gross;
    if (gross < p.mae) p.mae = gross;

    p.giveback = p.mfe - gross;

    // Armado ESCAPE_DIR: una vez armado no se desarma.
    if (!p.escapeArmed && p.mfe >= ESC.escapeArmMfeUsd) {
        p.escapeArmed = true;
        E.escapeArms++;
        E.dirty = true;

        node.log(
            ENGINE + ': slot ' + p.slot + ' ' + p.side + ' ESCAPE ARMED (MFE ' +
            p.mfe.toFixed(2) + ' >= ' + ESC.escapeArmMfeUsd.toFixed(2) + ')'
        );
    }

    let reason = null;
    let realized = gross;

    // Prioridad: 1) TP  2) SL  3) ESCAPE_DIR  4) TIMEOUT
    if (gross >= p.tp) {
        reason = 'TP';
        realized = p.tp;
    } else if (gross <= p.sl) {
        reason = 'SL';
        realized = p.sl;
    } else {
        const adverse = escapeAdverse(p, gross, p.giveback, m);

        if (adverse) {
            p.escapeConfirm = contiguous ? (p.escapeConfirm + 1) : 1;
        } else {
            if (p.escapeConfirm > 0) E.escapeConfirmResets++;
            p.escapeConfirm = 0;
        }

        if (adverse && p.escapeConfirm >= ESC.escapeConfirmSec) {
            reason = 'ESCAPE_DIR';
            realized = gross;
        } else if (b.t - p.entryT >= p.toMin * 60000) {
            reason = 'TIMEOUT';
        }
    }

    if (!reason) {
        // Checkpoint de MFE en la fila OPEN (al armar y cada +step).
        if (
            p.escapeArmed &&
            p.mfe >= ESC.escapeArmMfeUsd &&
            (
                !(p.mfeSaved >= ESC.escapeArmMfeUsd) ||
                p.mfe - p.mfeSaved >= ESC.mfeCheckpointStepUsd
            )
        ) {
            saveMfeCheckpoint(p);
        }
        return false;
    }

    // TIMEOUT y ESCAPE_DIR salen al GMX ejecutable del segundo.
    const exitPx = (reason === 'TIMEOUT' || reason === 'ESCAPE_DIR')
        ? px
        : (p.entryPx + k * realized / p.qty);

    const feeExit = (
        p.feeBase === 'exposure' ? p.exposure : p.qty * exitPx
    ) * p.feeRate;

    const fees = p.feeEntry + feeExit;
    const net = realized - fees;

    const x = {
        t: b.t,
        px: exitPx,
        trigger: px,
        gross: realized,
        feeExit: feeExit,
        fees: fees,
        net: net,
        reason: reason,
        dur: Math.round((b.t - p.entryT) / 1000)
    };

    saveRow(p, x);

    const T = E.totals;
    T.ops++;
    if (reason === 'TP') T.tp++;
    else if (reason === 'SL') T.sl++;
    else if (reason === 'ESCAPE_DIR') T.escape++;
    else T.to++;
    T.gross += realized;
    T.net += net;
    T.fees += fees;

    for (let i = E.trades.length - 1; i >= 0; i--) {
        if (E.trades[i].entryT === p.entryT) {
            Object.assign(E.trades[i], {
                exitT: b.t,
                exitPx: exitPx,
                reason: reason,
                net: net
            });
            break;
        }
    }

    E.lastClosed = {
        slot: p.slot,
        side: p.side,
        reason: reason,
        net: net,
        gross: realized,
        mfe: r(p.mfe, 2),
        mae: r(p.mae, 2),
        t: b.t,
        dur: x.dur
    };

    E.tradesRev++;
    E.dirty = true;

    node.log(
        ENGINE + ': cierra slot ' + p.slot + ' ' + p.side + ' por ' + reason +
        ' (close ' + px + ') · bruto ' + realized.toFixed(2) +
        ' · neto ' + net.toFixed(2) +
        (reason === 'ESCAPE_DIR'
            ? (' · MFE ' + p.mfe.toFixed(2) +
               ' · giveback ' + p.giveback.toFixed(2) +
               ' · slope35 ' + (m && m.slopeFastBps != null ? m.slopeFastBps.toFixed(2) : '-') +
               ' · slope70 ' + (m && m.slopeSlowBps != null ? m.slopeSlowBps.toFixed(2) : '-') +
               ' · spread ' + (m && m.spreadBps != null ? m.spreadBps.toFixed(2) : '-') +
               ' vs ' + (m && m.spreadBpsLag != null ? m.spreadBpsLag.toFixed(2) : '-') + ' bps')
            : '')
    );

    return true;
}

// m = métricas ESCAPE del mismo segundo b.t (E.esc), compartidas por todas
// las posiciones; cada posición evalúa su propio armado / giveback / contador.
function manageAll(b, m) {
    if (!E.positions.length) return 0;

    const keep = [];
    let closed = 0;

    for (let i = 0; i < E.positions.length; i++) {
        const p = E.positions[i];
        if (b.t > p.entryT && managePosition(p, b, m)) closed++;
        else keep.push(p);
    }

    E.positions = keep;
    return closed;
}


// ============================================================
// SEGUNDO GMX STALE (> 10 s sin cotización)
// ============================================================

function onGmxStale(T) {

    if (
        E.lastBucketT ||
        E.closes.length ||
        E.lastSign !== 0
    ) {
        E.gaps++;
    }

    resetSignal();

    // Rompe la continuidad: el próximo segundo válido arranca warmup.
    E.lastBucketT = 0;

    // Si N+1 es stale, no se fabrica entrada con una cotización futura.
    if (E.pend) {

        node.warn(
            ENGINE + ': entrada cancelada; GMX stale en N+1 (' +
            new Date(T).toISOString().slice(11, 19) +
            ')'
        );

        E.pend = null;

        E.ignored++;
    }

    E.dirty = true;
}


// ============================================================
// SEGUNDO GMX VÁLIDO — X10
// ============================================================

// b = { t, source_ts, min, max, mid }
// t es el boundary exacto (múltiplo de 1000 ms) y source_ts <= t.
function onGmxSecond(b) {

    if (E.lastBucketT && b.t - E.lastBucketT > 1000) {
        resetSignal();
        E.gaps++;
    }

    E.lastBucketT = b.t;

    // 1) Ejecutar una señal pendiente N → entrada N+1.
    // Sólo puede existir una pendiente porque cada cruce real genera como máximo una.
    if (E.pend) {
        if (b.t === E.pend.t + 1000) {
            if (!open(E.pend, b)) E.ignored++;
        } else {
            node.warn(ENGINE + ': entrada omitida; el segundo válido siguiente no es N+1');
            E.ignored++;
        }
        E.pend = null;
    }

    // 2) Precio de señal = GMX MID del segundo.
    //    (V2: la SMA del segundo se calcula ANTES de administrar posiciones
    //    para que ESCAPE_DIR use SMA(t). No depende de las posiciones ni
    //    altera la secuencia de entrada: el cruce, el cooldown, MOVEMENT y
    //    el chequeo de capacidad siguen evaluándose después de manageAll,
    //    exactamente como en V1.)
    const signalPx = b.mid;

    // 3) SMA FAST / SLOW sobre GMX MID.
    E.closes.push(signalPx);
    if (E.closes.length > C.slow) E.closes.shift();

    E.sF = avgLast(C.fast);
    E.sS = avgLast(C.slow);
    E.last = { t: b.t, px: signalPx };

    histPut(b.t, E.sF, E.sS);
    E.newPts.push(b.t, r(E.sF, 6), r(E.sS, 6));

    // 3b) Métricas causales ESCAPE_DIR del segundo b.t.
    const m = escapeMetrics(b.t, E.sF, E.sS);

    // 4) Administrar TODAS las posiciones abiertas de manera independiente
    //    (TP > SL > ESCAPE_DIR > TIMEOUT).
    manageAll(b, m);

    // 5) MOVIMIENTO ZEC: rango 30 min con datos hasta b.t.
    movePut(b.t, signalPx);

    if (E.sF == null || E.sS == null) return;

    // 6) Cruce real: cambio de signo SMA35-SMA70.
    const d = E.sF - E.sS;
    const sg = d > 0 ? 1 : (d < 0 ? -1 : 0);
    if (sg === 0) return;

    const cross = (E.lastSign !== 0 && sg !== E.lastSign) ? sg : 0;
    E.lastSign = sg;
    if (!cross) return;

    // 7) Anti-serrucho: todo cruce reinicia el reloj, aun descartado.
    const prevCrossT = E.lastCrossT || 0;
    const crossAllowed = !prevCrossT || (b.t - prevCrossT >= CROSS_COOLDOWN_MS);
    E.lastCrossT = b.t;

    if (!crossAllowed) {
        E.ignored++;
        return;
    }

    // 8) MOVEMENT OFF / WARMUP: registra cruce pero no abre.
    if (E.moveState !== 'ON') {
        if (E.moveState === 'WARMUP') E.crossesBlockedWarmup++;
        else E.crossesBlockedMovement++;
        E.dirty = true;
        return;
    }

    // 9) Capacidad X10. Una señal real puede crear como máximo UNA operación.
    if (E.positions.length >= C.maxPos) {
        E.rejectMaxPositions++;
        E.lastRejected = {
            reason: 'REJECT_MAX_POSITIONS',
            t: b.t,
            side: cross > 0 ? 'LONG' : 'SHORT'
        };
        E.dirty = true;
        return;
    }

    // 9b) V2 ENTRY_SPACING: separación global mínima entre aperturas efectivas.
    //     Rechazar NO modifica lastEntryT ni reinicia ningún reloj.
    const candidateEntryT = b.t + 1000;
    const spacingOk =
        !E.lastEntryT ||
        candidateEntryT - E.lastEntryT >= ENTRY_SPACING_MS;

    if (!spacingOk) {
        E.rejectEntrySpacing++;
        E.lastRejected = {
            reason: 'REJECT_ENTRY_SPACING',
            t: b.t,
            side: cross > 0 ? 'LONG' : 'SHORT',
            candidateEntryT: candidateEntryT,
            lastEntryT: E.lastEntryT,
            remainingSec: Math.ceil((E.lastEntryT + ENTRY_SPACING_MS - candidateEntryT) / 1000)
        };
        E.dirty = true;
        return;
    }

    // Salvaguarda: nunca duplicar una pendiente.
    if (E.pend) {
        E.ignored++;
        return;
    }

    E.pend = {
        signalId: String(b.t) + ':' + (cross > 0 ? 'LONG' : 'SHORT'),
        side: cross > 0 ? 'LONG' : 'SHORT',
        t: b.t,
        sF: E.sF,
        sS: E.sS
    };

    E.signalsAccepted++;
    E.dirty = true;
}


// ============================================================
// RELOJ GMX: AS-OF BACKWARD SOBRE SEGUNDOS COMPLETADOS
// ============================================================

function pumpGmx() {

    const G =
        global.get(
            'md_gmx',
            'memory'
        );

    const z =
        G &&
        G.last &&
        G.last[C.symbol];

    if (!z) {
        return;
    }

    const s = Number(z.source_ts);
    const mn = Number(z.min);
    const mx = Number(z.max);

    if (
        !isFinite(s) ||
        !isFinite(mn) ||
        !isFinite(mx) ||
        mn <= 0 ||
        mx <= 0
    ) {
        return;
    }

    // Sólo cotizaciones nuevas (source_ts estrictamente mayor).
    if (s <= E.lastGmxSourceTs) {
        return;
    }

    const prev =
        E.lastGmxQuote;

    if (prev) {

        // Llegó una cotización con source_ts = s:
        // todos los boundaries T < s ya están completos y su
        // cotización as-of es 'prev' (source_ts <= T).
        let T =
            E.nextGmxBoundary;

        while (T < s) {

            if (
                T - prev.source_ts >
                GMX_MAX_AGE_MS
            ) {

                // Todos los T restantes < s también son stale.
                onGmxStale(T);

                T =
                    Math.ceil(
                        s /
                        1000
                    ) *
                    1000;

                break;
            }

            onGmxSecond({
                t: T,
                source_ts: prev.source_ts,
                min: prev.min,
                max: prev.max,
                mid: (prev.min + prev.max) / 2
            });

            E.dirty = true;

            T += 1000;
        }

        E.nextGmxBoundary = T;
    }

    else {

        // Primera cotización tras deploy/restore:
        // el primer boundary procesable es el primero >= s.
        E.nextGmxBoundary =
            Math.ceil(
                s /
                1000
            ) *
            1000;
    }

    E.lastGmxQuote = {
        source_ts: s,
        min: mn,
        max: mx
    };

    E.lastGmxSourceTs = s;
}


// ============================================================
// ESTADO DASHBOARD / DEBUG X10
// ============================================================

function state() {
    const m = E.esc || {};

    const pos = E.positions.map(function (p) {
        const L = levels(p);
        return {
            slot: p.slot,
            signalId: p.signalId,
            side: p.side,
            entryT: p.entryT,
            entryPx: p.entryPx,
            lastPx: p.lastPx,
