            t: m.t || null,
            slopeFastBps: r(m.slopeFastBps, 3),
            slopeSlowBps: r(m.slopeSlowBps, 3),
            spreadBps: r(m.spreadBps, 3),
            spreadBpsLag: r(m.spreadBpsLag, 3),
            arms: E.escapeArms,
            confirm_resets: E.escapeConfirmResets
        },

        totals: {
            ops: E.totals.ops,
            tp: E.totals.tp,
            sl: E.totals.sl,
            escape: E.totals.escape,
            to: E.totals.to,
            gross: r(E.totals.gross, 2),
            net: r(E.totals.net, 2),
            fees: r(E.totals.fees, 2)
        },

        pend: E.pend ? {
            signalId: E.pend.signalId,
            side: E.pend.side,
            t: E.pend.t
        } : null,

        lastClosed: E.lastClosed,
        lastRejected: E.lastRejected,
        signals_accepted: E.signalsAccepted,
        reject_max_positions: E.rejectMaxPositions,
        ignored: E.ignored,

        entry_spacing_min: Number(C.entrySpacingMin),
        last_entry_t: E.lastEntryT || null,
        reject_entry_spacing: E.rejectEntrySpacing,
        entry_spacing_remaining_sec: spacingRemainingSec(),

        movement_state: E.moveState,
        movement_on: E.moveState === 'ON',
        range30_bps: r(E.r30Bps, 2),
        range30_pct: E.r30Bps == null ? null : r(E.r30Bps / 100, 4),
        movement_threshold_bps: MOVE_THRESHOLD_BPS,
        range30_high: r(E.r30High, 6),
        range30_low: r(E.r30Low, 6),
        range30_warm_sec: moveWarmSec(),
        range30_window_sec: MOVE_WINDOW_MS / 1000,
        crosses_blocked_movement: E.crossesBlockedMovement,
        crosses_blocked_warmup: E.crossesBlockedWarmup,

        db: {
            ok: E.dbOk,
            err: E.dbErr,
            errors: E.dbErrors,
            queue: E.q.length + (E.inflight ? 1 : 0),
            saved: E.saved
        }
    };
}

function cfgOut() {
