    };
}

function recentTrades() {

    const lim =
        now -
        C.histSec *
        1000;

    return E.trades.filter(
        function (t) {
            return (
                t.exitT ||
                now
            ) >= lim;
        }
    );
}

function mmss(sec) {
    return pad(Math.floor(sec / 60)) + ':' + pad(sec % 60);
}

// WARMUP → MOVEMENT OFF → MOVEMENT ON
function moveTag() {

    if (E.moveState === 'WARMUP') {
        return (
            'WARMUP ' +
            mmss(moveWarmSec()) +
            '/' +
            mmss(MOVE_WINDOW_MS / 1000)
        );
    }

    return (
        'MOVEMENT ' +
        E.moveState +
        ' ' +
        (E.r30Bps == null ? '-' : E.r30Bps.toFixed(1)) +
        '/' +
        MOVE_THRESHOLD_BPS +
        'bps'
    );
}

function statusText() {
    if (E.phase !== 'OPERANDO') {
        return {
            fill: 'yellow',
            shape: 'ring',
            text: ENGINE + ' · restaurando estado (MariaDB)' + (E.dbErr ? ': ' + E.dbErr.slice(0, 40) : '')
        };
    }

    const tail =
        ' · abiertas ' + E.positions.length + '/' + C.maxPos +
        ' · ops ' + E.totals.ops +
        ' · esc ' + E.totals.escape +
        ' · neto ' + E.totals.net.toFixed(2) +
        ' · maxrej ' + E.rejectMaxPositions +
        ' · spacing ' + C.entrySpacingMin + 'm' +
        (spacingRemainingSec() > 0 ? (' resta ' + mmss(spacingRemainingSec())) : ' libre') +
        ' rech ' + E.rejectEntrySpacing +
        (E.escapeEnabled ? '' : ' · ESCAPE OFF (schema)');

    return {
        fill: E.moveState === 'ON' ? 'blue' : (E.moveState === 'OFF' ? 'grey' : 'yellow'),
        shape: E.moveState === 'ON' ? 'dot' : 'ring',
        text: moveTag() + ' · ' +
            (E.sS == null ? ('calentando SMA ' + E.closes.length + '/' + C.slow) : 'esperando cruce') +
            tail
    };
}


// ============================================================
// ERROR DB
// ============================================================

if (
    msg.topic === 'db_error' ||
    msg.error
) {

    if (
        E.inflight &&
        msg.cxBatch ===
        E.inflight.id
    ) {

        fail(
            (
                msg.error &&
                msg.error.message
            ) ||
            'error DB'
        );
    }

    return null;
}


// ============================================================
// RESPUESTAS MYSQL
// ============================================================

if (msg.cxKind) {

    if (
        !E.inflight ||
        msg.cxBatch !==
        E.inflight.id
    ) {
        return null;
    }

    const kind =
        E.inflight.kind;

    E.lastItem =
        E.inflight.item;

    E.inflight =
        null;

    E.backoff =
        0;

    E.dbOk =
        true;

    E.dbErr =
        '';


    // ========================================================
    // RESTORE X10
    // ========================================================

    if (kind === 'restore') {
        const sets = (Array.isArray(msg.payload) ? msg.payload : []).filter(Array.isArray);
        const opens = sets[0] || [];
        const tot = (sets[1] || [])[0] || {};
        const recent = sets[2] || [];
        const colInfo = (sets[3] || [])[0] || null;

        // V2: verificación NO destructiva de que exit_reason acepta 'ESCAPE_DIR'.
        // Si la columna es ENUM sin ese valor o (VAR)CHAR < 10, ESCAPE_DIR se
        // deshabilita (para no corromper filas ni bloquear la cola DB) y se avisa.
        // Sin metadata (consulta vacía) también se deshabilita: fail closed.
        // El motor nunca ejecuta ALTER.
        if (colInfo) {
            const ctype = String(colInfo.ctype || '').toLowerCase();
            const dtype = String(colInfo.dtype || '').toLowerCase();
            const clen = colInfo.clen == null ? null : Number(colInfo.clen);

            let ok = true;
            let why = ctype;

            if (dtype === 'enum') {
                ok = ctype.indexOf('\'escape_dir\'') >= 0;
                if (!ok) why = 'ENUM sin ESCAPE_DIR: ' + ctype;
            } else if (dtype === 'char' || dtype === 'varchar') {
                ok = clen == null || clen >= 'ESCAPE_DIR'.length;
                if (!ok) why = dtype + '(' + clen + ') < 10';
            }

            E.escapeEnabled = ok;
            E.schemaInfo = ok ? ('OK ' + ctype) : ('INCOMPATIBLE: ' + why);

            if (!ok) {
                node.warn(
                    ENGINE + ': exit_reason no acepta ESCAPE_DIR (' + why +
                    '). ESCAPE_DIR DESHABILITADO hasta corregir el schema manualmente ' +
                    '(ver comment del flow). El motor sigue como V1.'
                );
            }
        } else {
            // Fail closed: sin metadata no se habilita ESCAPE_DIR.
            E.escapeEnabled = false;
            E.schemaInfo = 'NO VERIFICADO: information_schema sin metadata de exit_reason';
            node.warn(
                ENGINE + ': no se pudo verificar exit_reason en information_schema. ' +
                'ESCAPE_DIR DESHABILITADO (fail closed). El motor sigue como V1 + ENTRY_SPACING.'
            );
        }

        E.openRows = Number(tot.open_rows || 0);

        // V2 ENTRY_SPACING: última entrada (OPEN o CLOSED) del source V2,
        // para que un deploy/restart no permita saltarse el spacing.
        E.lastEntryT = tot.last_entry_ms == null ? 0 : (Number(tot.last_entry_ms) || 0);
        E.positions = [];

        const used = new Set();
        function allocSlot() {
            for (let s = 1; s <= C.maxPos; s++) {
                if (!used.has(s)) { used.add(s); return s; }
            }
            return null;
        }

        for (let i = 0; i < opens.length && E.positions.length < C.maxPos; i++) {
            const op = opens[i];
            const slot = allocSlot();
            if (slot == null) break;

            // V2: MFE/MAE desde el último checkpoint persistido en la fila OPEN
            // (si no hay checkpoint quedan en 0). ARMED se recalcula desde MFE.
            // El contador de confirmación siempre reinicia en 0.
            const rMfe = Math.max(0, num(op.mfe_usd) || 0);
            const rMae = Math.min(0, num(op.mae_usd) || 0);

            E.positions.push({
                slot: slot,
                signalId: String(op.signal_ms == null ? Number(op.entry_ms) - 1000 : Number(op.signal_ms)) + ':' + op.side,
                side: op.side,
                signalT: op.signal_ms == null ? Number(op.entry_ms) - 1000 : Number(op.signal_ms),
                entryT: Number(op.entry_ms),
                entryPx: num(op.entry_price),
                qty: num(op.qty),
                margin: num(op.margin_usd),
                lev: num(op.leverage),
                exposure: num(op.exposure_usd),
                fast: Number(op.sma_fast),
                slow: Number(op.sma_slow),
                sFast: num(op.sma_fast_entry),
                sSlow: num(op.sma_slow_entry),
                tp: num(op.tp_usd),
                sl: num(op.sl_usd),
                toMin: num(op.timeout_min),
                feeRate: num(op.fee_rate),
                feeBase: C.feeBase,
                feeEntry: num(op.fee_entry),
                pnl: 0,
                mfe: rMfe,
                mae: rMae,
                lastPx: num(op.entry_price),
                lastT: Number(op.entry_ms),

                // ESCAPE_DIR (V2)
                giveback: 0,
                escapeArmed: rMfe >= ESC.escapeArmMfeUsd,
                escapeConfirm: 0,
                escapeLastT: 0,
                mfeSaved: rMfe,
                restored: true
            });
        }

        if (E.openRows > C.maxPos) {
            node.warn(ENGINE + ': hay ' + E.openRows + ' filas OPEN ' + SRC +
                '; se restauran como máximo ' + C.maxPos);
        }

        E.totals = {
            ops: Number(tot.ops || 0),
            tp: Number(tot.tp || 0),
            sl: Number(tot.sl || 0),
            escape: Number(tot.escape || 0),
            to: Number(tot.tmo || 0),
            gross: num(tot.gross) || 0,
            net: num(tot.net) || 0,
            fees: num(tot.fees) || 0
        };

        E.trades = recent.map(function (x) {
            if (x.exit_ms == null) {
                return {
                    entryT: Number(x.entry_ms),
                    entryPx: num(x.entry_price),
                    side: x.side
                };
            }
            return {
                entryT: Number(x.entry_ms),
                entryPx: num(x.entry_price),
                side: x.side,
                exitT: Number(x.exit_ms),
                exitPx: num(x.exit_price),
                reason: x.exit_reason,
                net: num(x.net_pnl)
            };
        });

        E.tradesRev++;

        // Igual que el motor original: sin replay; SMA, movimiento y cooldown recalientan.
        E.replayUntil = 0;
        E.lastGmxSourceTs = 0;
        E.lastGmxQuote = null;
        E.nextGmxBoundary = 0;
        E.lastBucketT = 0;
        resetSignal();
        resetMovement();
        E.lastCrossT = 0;
        E.pend = null;
        E.phase = 'OPERANDO';

        node.log(
            ENGINE + ': operando (' + SRC + ' · ops ' + E.totals.ops +
            ' · escape ' + E.totals.escape +
            ' · abiertas restauradas ' + E.positions.length + '/' + C.maxPos +
            ' · exit_reason ' + E.schemaInfo +
            ' · spacing ' + C.entrySpacingMin + 'm resta ' + spacingRemainingSec() + 's' +
            ') · WARMUP SMA ' + C.fast + '/' + C.slow +
            ' + rango ' + (MOVE_WINDOW_MS / 60000) + ' min → MOVEMENT OFF / ON'
        );

        E.dirty = true;
        node.status(statusText());
        return null;
    }


    if (
        kind === 'close' &&
        msg.payload &&
        msg.payload.affectedRows === 0 &&
        E.lastItem &&
        E.lastItem.fallback
    ) {

        E.q.unshift(
            E.lastItem.fallback
        );
    }

    else {
        E.saved++;
    }

    return null;
}


// ============================================================
// SNAPSHOT DASHBOARD
// ============================================================

if (
    msg.topic ===
    'cx_snapshot_req'
) {

    const H =
        E.hist;

    const since =
        Math.floor(
            (
                Number(
                    msg.since
                ) ||
                0
            ) /
            1000
        );

    const nowSec =
        Math.floor(
            now /
            1000
        );

    const arr =
        [];

    for (
        let s =
            Math.max(
                since + 1,
                nowSec -
                H.cap +
                1
            );

        s <= nowSec;

        s++
    ) {

        const k =
            s %
            H.cap;

        if (
            H.idx[k] ===
            s
        ) {

            arr.push(
                s * 1000,
                r(H.a[k], 6),
                r(H.b[k], 6)
            );
        }
    }

    out[1] = {
        socketid:
            msg.socketid,

        payload: {
            cx10v2Snap: {
                cfg:
                    cfgOut(),

                sma:
                    arr,

                trades:
                    recentTrades(),

                state:
                    state()
            }
        }
    };

    return out;
}


// ============================================================
// SÓLO TICK
// ============================================================

if (
    msg.topic !==
    'tick'
) {
    return null;
}


// ============================================================
// DB TIMEOUT
// ============================================================

if (
    E.inflight &&
    now -
    E.inflight.sentAt >
    30000
) {

    fail(
        'timeout: MariaDB no respondió en 30 s'
    );
}


// ============================================================
// RESTAURAR ESTADO
// ============================================================

if (
    E.phase ===
    'RESTAURANDO' &&

    !E.inflight &&

    !E.q.some(
        function (i) {
            return (
                i.kind ===
                'restore'
            );
        }
    ) &&

    now >=
    E.nextTry
) {

    const T =
        C.table;

    const ms =
        function (c) {

            return (
                'TIMESTAMPDIFF(MICROSECOND, ' +
                '\'1970-01-01 00:00:00\', ' +
                c +
                ') DIV 1000'
            );
        };

    E.q.unshift({
        kind: 'restore',

        sql:
            'SELECT ' +
            ms('entry_ts') + ' AS entry_ms, ' +
            'CASE WHEN signal_ts IS NULL THEN NULL ELSE ' + ms('signal_ts') + ' END AS signal_ms, ' +
            'side, entry_price, qty, margin_usd, leverage, exposure_usd, ' +
            'sma_fast, sma_slow, sma_fast_entry, sma_slow_entry, ' +
            'tp_usd, sl_usd, timeout_min, fee_rate, fee_entry, mfe_usd, mae_usd ' +
            'FROM ' + T + ' WHERE symbol = ? AND source = ? AND status = \'OPEN\' ' +
            'ORDER BY entry_ts ASC LIMIT ' + C.maxPos + '; ' +

            'SELECT ' +
            'SUM(status = \'CLOSED\') ops, ' +
            'SUM(exit_reason = \'TP\') tp, ' +
            'SUM(exit_reason = \'SL\') sl, ' +
            'SUM(exit_reason = \'ESCAPE_DIR\') `escape`, ' +
            'SUM(exit_reason = \'TIMEOUT\') tmo, ' +
            'SUM(CASE WHEN status = \'CLOSED\' THEN gross_pnl END) gross, ' +
            'SUM(CASE WHEN status = \'CLOSED\' THEN net_pnl END) net, ' +
            'SUM(CASE WHEN status = \'CLOSED\' THEN fees END) fees, ' +
            'SUM(status = \'OPEN\') open_rows, ' +
            'MAX(' + ms('entry_ts') + ') AS last_entry_ms ' +
            'FROM ' + T + ' WHERE symbol = ? AND source = ?; ' +

            'SELECT ' +
            ms('entry_ts') + ' AS entry_ms, ' +
            'CASE WHEN exit_ts IS NULL THEN NULL ELSE ' + ms('exit_ts') + ' END AS exit_ms, ' +
            'side, entry_price, exit_price, exit_reason, net_pnl ' +
            'FROM ' + T + ' WHERE symbol = ? AND source = ? ' +
            'AND (exit_ts IS NULL OR exit_ts >= ?) ORDER BY entry_ts; ' +

            // V2: sólo lectura de metadatos (no modifica nada).
            'SELECT COLUMN_TYPE AS ctype, DATA_TYPE AS dtype, ' +
            'CHARACTER_MAXIMUM_LENGTH AS clen ' +
            'FROM information_schema.COLUMNS ' +
            'WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? ' +
            'AND COLUMN_NAME = \'exit_reason\'',

        params: [
            C.symbol, SRC,
            C.symbol, SRC,
            C.symbol, SRC,
            dt(now - C.histSec * 1000),
            T
        ]
    });
}


// ============================================================
// ENVIAR QUERY MYSQL
// ============================================================

if (
    !E.inflight &&
    E.q.length &&
    now >=
    E.nextTry
) {

    const it =
        E.q.shift();

    E.inflight = {
        id:
            ++E.seq,

        kind:
            it.kind,

        item:
            it,

        sentAt:
            now
    };

    out[0] = {
        topic:
            it.sql,

        payload:
            it.params,

        cxKind:
            it.kind,

        cxBatch:
            E.inflight.id,

        cxRow:
            it.row
    };
}


// ============================================================
// PROCESAR SEGUNDOS GMX
// ============================================================

if (
    E.phase ===
    'OPERANDO'
) {
    pumpGmx();
}


// ============================================================
// EMITIR DASHBOARD
// ============================================================

if (
    E.dirty &&
    now -
    E.lastEmit >=
    250
) {

    E.dirty =
        false;

    E.lastEmit =
        now;

    const p = {
        cx10v2: {
            state:
                state(),

            pts:
                E.newPts
        }
    };

    E.newPts =
        [];

    if (
        E.tradesRev !==
        E.sentRev
    ) {

        p.cx10v2.trades =
            recentTrades();

        p.cx10v2.cfg =
            cfgOut();

        E.sentRev =
            E.tradesRev;
    }

    out[1] = {
        payload:
            p
    };

    node.status(
        statusText()
    );
}

return (
    out[0] ||
    out[1]
)
    ? out
    : null;

// Historial X10 V2: últimas 100 operaciones CERRADAS de GMX_MOV_X10_V2_ESCAPE.
// Sólo lectura. No modifica el motor ni la tabla. Nunca consulta el source de V1.
msg.topic =
    "SELECT " +
    "TIMESTAMPDIFF(MICROSECOND,'1970-01-01 00:00:00',exit_ts) DIV 1000 AS exit_ms, " +
    "side, entry_price, exit_price, exit_reason, duration_seconds, " +
    "mfe_usd, mae_usd, gross_pnl, fees, net_pnl " +
    "FROM conceptito_trades " +
    "WHERE symbol = ? AND source = ? AND status = 'CLOSED' " +
    "ORDER BY exit_ts DESC LIMIT 100";

msg.payload = ['ZEC','GMX_MOV_X10_V2_ESCAPE'];
return msg;

// Empaqueta el resultado para el ui_template V2.
msg.payload = {
    cx10v2History: Array.isArray(msg.payload) ? msg.payload : []
};
return msg;
